news.css:
.article-aespa {
  font-feature-settings: "palt";
}

.article-aespa a {
  color: #FED100;
  text-decoration: underline;
}

.article-aespa .yt-link {
  position: relative;
}

.article-aespa .yt-link::after {
  background: url(https://stg-wp.streetfighter.com/6/wp-content/uploads/sites/2/2025/06/yt_icon_b.png) center no-repeat;
  background-size: contain;
  content: "";
  display: block;
  height: 22%;
  left: 50%;
  max-width: 135px;
  opacity: 0.8;
  position: absolute;
  top: 50%;
  transition: background 0.25s ease, opacity 0.25s ease;
  transform: translate(-50%, -50%);
  width: 18%;
}

.article-aespa .yt-link:hover::after {
  background: url(https://stg-wp.streetfighter.com/6/wp-content/uploads/sites/2/2025/06/yt_icon_r.png) center no-repeat;
  background-size: contain;
  opacity: 1;
}

.article-aespa .sec-frame {
  margin: min(24px, 8vw) 0;
  padding: 0 min(24px, 8vw);
  border: 1px solid #6d25ff;
}

.article-aespa .sec-frame .col-2 {
  display: flex;
  justify-content: space-between;
  gap: 1.2em;
}

.article-aespa .sec-frame .col-2_btn {
  width: 50%;
  display: block;
  padding: 0.8em 0;
  background: #6d25ff;
  color: #fff;
  font-weight: bold;
  text-align: center;
  clip-path: polygon(.78125vw 0, 100% 0, 100% calc(100% - .78125vw), calc(100% - .78125vw) 100%, 0 100%, 0 .78125vw);
}

.article-aespa .sec-frame .col-2_btn:hover {
  opacity: 0.8;
}

@media screen and (max-width: 767.9px) {
  .article-aespa .sec-frame .col-2 {
    flex-direction: column;
  }
  .article-aespa .sec-frame .col-2_btn {
    width: 100%;
    clip-path: polygon(min(1.9556714472vw,15px) 0,100% 0,100% calc(100% - min(1.9556714472vw, 15px)),calc(100% - min(1.9556714472vw, 15px)) 100%,0 100%,0 min(1.9556714472vw,15px));
  }
}
